//! `DebugInspector` against the pinned CesiumJS cases in
//! `tests/data/scene-debug-inspector.json` (generated by
//! `tools/cesium/generate-scene-debug-inspector.mjs`), executed through a
//! recording WebGL host.

use cesium_rs::core::{math, RuntimeError};
use cesium_rs::renderer::*;
use cesium_rs::scene::{create_debug_show_frustums_uniform_map, DebugInspector, DebugShowOptions};
use serde_json::{json, Value};
use std::{
    cell::{Cell, RefCell},
    collections::BTreeMap,
    rc::Rc,
};

const ACTIVE_ATTRIBUTES: f64 = 35721.0;
const ACTIVE_UNIFORMS: f64 = 35718.0;

/// Records every call. Programs report the attribute names in `active` as
/// their active attributes, so attribute locations can be checked.
#[derive(Clone, Default)]
struct Host {
    calls: Rc<RefCell<Vec<String>>>,
    next: Rc<Cell<u32>>,
    active: Rc<RefCell<Vec<String>>>,
}

impl Gl for Host {
    type Object = u32;
    fn drawing_buffer_size(&self) -> Result<[u32; 2], RuntimeError> {
        Ok([64, 64])
    }
    fn invoke(&self, name: &str, args: &[GlValue<u32>]) -> Result<GlValue<u32>, RuntimeError> {
        self.calls.borrow_mut().push(name.into());
        let pname = args.get(1).and_then(|v| match v {
            GlValue::Number(n) => Some(*n),
            _ => None,
        });
        Ok(if name.starts_with("create") {
            self.next.set(self.next.get() + 1);
            GlValue::Object(self.next.get())
        } else {
            match name {
                "getParameter" => {
                    if args
                        .first()
                        .is_some_and(|v| matches!(v, GlValue::Number(n) if [33901., 33902., 3386.].contains(n)))
                    {
                        GlValue::Numbers(vec![1., 4096.])
                    } else {
                        GlValue::Number(4096.)
                    }
                }
                "getExtension" => GlValue::Object(0),
                "getProgramParameter" if pname == Some(ACTIVE_ATTRIBUTES) => {
                    GlValue::Number(self.active.borrow().len() as f64)
                }
                "getProgramParameter" if pname == Some(ACTIVE_UNIFORMS) => GlValue::Number(0.0),
                "getActiveAttrib" => {
                    let index = match args.get(1) {
                        Some(GlValue::Number(n)) => *n as usize,
                        _ => 0,
                    };
                    GlValue::Record(json!({"name": self.active.borrow()[index], "type": 35665, "size": 1}))
                }
                "getShaderParameter" | "getProgramParameter" => GlValue::Bool(true),
                _ => GlValue::Null,
            }
        })
    }
}

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-debug-inspector.json")).unwrap()
}

fn strings(v: &Value) -> Vec<String> {
    v.as_array().unwrap().iter().map(|s| s.as_str().unwrap().to_string()).collect()
}

fn f32s(color: &Value) -> Vec<f32> {
    color.as_array().unwrap()[..3].iter().map(|v| v.as_f64().unwrap() as f32).collect()
}

#[test]
fn debug_frustum_commands_match_reference() {
    let fixture = fixture();
    let fragments = &fixture["fragments"];
    for case in fixture["cases"].as_array().unwrap() {
        let scene = &case["scene"];
        let options = DebugShowOptions {
            debug_show_commands: scene["debugShowCommands"].as_bool().unwrap(),
            debug_show_frustums: scene["debugShowFrustums"].as_bool().unwrap(),
        };
        math::set_random_number_seed(case["seed"].as_u64().unwrap() as u32);

        let host = Host::default();
        let ctx = Context::new_webgl2(host.clone());
        let mut cache = ShaderCache::new(&ctx);
        let mut make = |fragment: &str, attributes: &[(&str, u32)]| {
            *host.active.borrow_mut() = attributes.iter().map(|(n, _)| n.to_string()).collect();
            cache
                .get_shader_program(&ShaderProgramOptions {
                    vertex_shader_source: ShaderSource {
                        defines: vec!["VS".into()],
                        sources: vec!["in vec3 position; void main() { gl_Position = vec4(position, 1.0); }".into()],
                        ..Default::default()
                    },
                    fragment_shader_source: ShaderSource {
                        defines: vec!["FS".into()],
                        sources: strings(&fragments[fragment]),
                        ..Default::default()
                    },
                    attribute_locations: attributes.iter().map(|(n, l)| (n.to_string(), *l)).collect(),
                })
                .unwrap()
        };
        let single = make("single", &[("position", 0)]);
        let multi = make("multi", &[("position", 0), ("normal", 3)]);
        let no_main = make("noMain", &[]);
        let va = VertexArray::new(&ctx, vec![VertexAttribute::constant(0, vec![0.])], None).unwrap();

        let mut commands = vec![
            DrawCommand::new(&va, &single),
            DrawCommand::new(&va, &multi),
            DrawCommand::new(&va, &single),
            DrawCommand::new(&va, &no_main),
        ];
        for (command, overlap) in commands.iter_mut().zip([1, 6, 7, 0]) {
            command.metadata.debug_overlapping_frustums = overlap;
        }
        commands[1].uniform_map = Some(Rc::new(|| Ok(vec![("a".into(), UniformValue::Float(vec![0.25]))])));
        // Cesium's sentinel is a string; any value shows the map is used as is.
        commands[2].uniform_map =
            Some(Rc::new(|| Ok(vec![("debugShowFrustumsColor".into(), UniformValue::Float(vec![9.0]))])));

        let mut inspector = DebugInspector::new();
        let programs_before = host.calls.borrow().iter().filter(|c| *c == "createProgram").count();
        for _ in 0..2 {
            for command in &commands {
                inspector
                    .execute_debug_show_frustums_command(options, &ctx, &mut cache, command, &PassState::default())
                    .unwrap();
            }
        }
        let calls = host.calls.borrow().clone();
        let programs_created = calls.iter().filter(|c| *c == "createProgram").count() - programs_before;
        let draws = calls.iter().filter(|c| *c == "drawArrays" || *c == "drawElements").count();

        // Shader cache requests, in order of first use.
        let requests = case["requests"].as_array().unwrap();
        assert_eq!(inspector.number_of_cached_programs(), requests.len(), "{scene}");
        assert_eq!(programs_created, requests.len(), "{scene}: one debug program per source program");
        assert_eq!(draws, 8, "{scene}: every command is drawn twice");
        for (source, request) in [&single, &multi, &no_main].into_iter().zip(requests) {
            let debug = inspector.cached_program(source).expect("cached debug program");
            let o = debug.source_options().unwrap();
            assert_eq!(o.vertex_shader_source.defines, strings(&request["vertex"]["defines"]));
            assert_eq!(o.vertex_shader_source.sources, strings(&request["vertex"]["sources"]));
            assert_eq!(o.fragment_shader_source.defines, strings(&request["fragment"]["defines"]));
            assert_eq!(o.fragment_shader_source.sources, strings(&request["fragment"]["sources"]), "{scene}");
            let locations: BTreeMap<String, u32> =
                serde_json::from_value(request["attributeLocations"].clone()).unwrap();
            assert_eq!(o.attribute_locations, locations, "{scene}");
        }

        // Uniforms: the first round of draws, one per command.
        let draws = case["draws"].as_array().unwrap();
        for (i, (command, draw)) in commands.iter().zip(draws).enumerate() {
            let expected = &draw["uniforms"];
            let commands_color = &expected["debugShowCommandsColor"];
            if options.debug_show_commands && commands_color.is_array() {
                // The persistent random color, all four components, exactly.
                let color = command.metadata.debug_color.get().expect("random command color");
                let rgba = [color.red, color.green, color.blue, color.alpha];
                let expected: Vec<f64> =
                    commands_color.as_array().unwrap().iter().map(|v| v.as_f64().unwrap()).collect();
                assert_eq!(rgba.to_vec(), expected, "{scene} command {i}");
            } else {
                assert!(command.metadata.debug_color.get().is_none(), "{scene} command {i}: no random color drawn");
            }
            let map = create_debug_show_frustums_uniform_map(options, command).unwrap();
            let values: BTreeMap<String, UniformValue> = map().unwrap().into_iter().collect();
            if expected["debugShowFrustumsColor"] == "mine" {
                assert_eq!(values.len(), 1, "{scene} command {i}: an existing debug uniform keeps the map");
                continue;
            }
            assert_eq!(values["debugShowCommandsColor"], UniformValue::Float(f32s(commands_color)), "{scene} {i}");
            assert_eq!(
                values["debugShowFrustumsColor"],
                UniformValue::Float(f32s(&expected["debugShowFrustumsColor"])),
                "{scene} {i}"
            );
            if expected.get("a").is_some() {
                assert_eq!(values["a"], UniformValue::Float(vec![0.25]));
            }
        }
    }
}
